# Parse numbers from lines: {items}
items = {items}
numbers = []
for line in items:
    s = str(line).strip()
    if not s:
        continue
    try:
        if '.' in s or 'e' in s.lower():
            numbers.append(float(s))
        else:
            numbers.append(int(s))
    except ValueError:
        continue
return numbers
